'use strict';
// Full-screen map directory, georeferenced city camera, and editorial media spreads.
let filmMap=null,mapReady=false,activeCity=null,activeStop=null,cityMarkers=[],stopMarkers=[],sceneToken=0;
function scenePlaybackSpeed(scene=playback.scenes[playback.index]){return scene?.type==='video'?1:(playback.speed||1)*(scene?.type==='spread'||scene?.type==='photo'?2:3);}
const EMPTY_GEO={type:'FeatureCollection',features:[]};
