function showMediaCaption(t,s,counter){$('#media-location').textContent=s.name+(s.en?' / '+s.en:'')+(isSingleDayTrip(t)?'':' · Day '+(s.day||1));$('#media-counter').textContent=counter;$('#media-cinema').hidden=false;$('#film-stage').classList.add('media-open');}
function prepareTyping(scene){const cps=Math.max(4,Math.min(24,+state.settings.typeSpeed||6))*2,hold=1000,delay=(scene.camera||0)*1000/scenePlaybackSpeed(scene)+350;playback.typing=[];for(const el of $$('[data-typewriter]')){if(el.hidden||getComputedStyle(el).visibility==='hidden'||getComputedStyle(el).display==='none'||el.closest('[hidden]'))continue;const full=el.dataset.fullText||'';if(!full)continue;const chars=Array.from(full),scrollBox=el.closest('.kind-text')||el,duration=chars.length/cps*1000+hold;playback.typing.push({el,chars,cps,hold,delay,scrollBox});playback.typingBudget=Math.max(playback.typingBudget,delay+duration);el.textContent='';scrollBox.scrollTop=0;el.classList.add('is-typing');}if(scene.type!=='video')playback.duration=Math.max(playback.duration,playback.typingBudget);}
function updateTyping(time){for(const item of playback.typing||[]){const elapsed=Math.max(0,time-item.delay),count=Math.min(item.chars.length,Math.floor(elapsed/1000*item.cps)),next=item.chars.slice(0,count).join('');if(item.el.textContent!==next)item.el.textContent=next;item.el.classList.toggle('is-typing',time>=item.delay&&count<item.chars.length);const box=item.scrollBox,target=Math.max(0,box.scrollHeight-box.clientHeight);box.scrollTop+= (target-box.scrollTop)*.22;}}
function stickerHTML(key){return ['flower','reading','stretch','box'].includes(key)?`<div class="collage-sticker sticker-${key}" role="img" aria-label="猫猫拼贴贴纸"></div>`:'';}
function openStickerLibrary(tid){const t=tripById(tid);if(!t)return;const chosen=t.design?.sticker;showDialog('拼贴素材库',`<p>贴纸只用于这个地点的照片拼版，不放在地图上。</p><div class="sticker-library">${[['flower','抱花猫'],['reading','读书猫'],['stretch','伸懒腰'],['box','纸箱猫']].map(([key,name])=>`<button class="sticker-choice ${chosen===key?'selected':''}" data-sticker="${key}">${stickerHTML(key)}<span>${name}</span></button>`).join('')}</div><div class="form-actions"><button class="text-btn" id="no-sticker">不使用贴纸</button><button class="primary-btn" id="back-spread-design">返回地点排版</button></div>`);$$('[data-sticker]').forEach(b=>b.onclick=()=>{t.design={palette:mapPaletteFor(t),layout:'auto',...t.design,sticker:b.dataset.sticker};save();$$('[data-sticker]').forEach(x=>x.classList.toggle('selected',x===b));toast('已加入这个地点的拼贴。');});$('#no-sticker').onclick=()=>{if(t.design)t.design.sticker=null;save();$$('[data-sticker]').forEach(x=>x.classList.remove('selected'));};$('#back-spread-design').onclick=()=>openSpreadDesign(t.id);}
function tick(now){if(!playback.running)return;const delta=Math.min(200,now-playback.last);playback.last=now;if(!playback.paused&&playback.ready){if(playback.video&&!playback.videoFinished)playback.elapsed=Math.max(0,(playback.video.currentTime-playback.videoStart)*1000);else playback.elapsed+=delta*scenePlaybackSpeed();playback.typingElapsed=(playback.typingElapsed||0)+delta;updateTyping(playback.typingElapsed);const textTimed=playback.scenes[playback.index]?.type!=='video'&&playback.typingBudget>0;const progress=Math.min(1,textTimed?playback.typingElapsed/playback.typingBudget:playback.elapsed/playback.duration);$('#play-progress').style.width=`${(playback.index+progress)/playback.scenes.length*100}%`;if(progress>=1&&(playback.scenes[playback.index]?.type==='video'||playback.typingElapsed>=playback.typingBudget)){nextScene();return;}}playback.raf=requestAnimationFrame(tick);}
function updateCameraSpeed(){if(!filmMap||!playback.target)return;const remain=playback.cameraTime-playback.elapsed;if(remain>100)filmMap.flyTo({...playback.target,duration:remain/scenePlaybackSpeed(),essential:true});}
function togglePause(force){if(!playback.running)return;const p=force===true?true:!playback.paused;if(p){filmMap?.stop();playback.video?.pause();playback.audio?.pause();playback.fadingAudio?.pause();}else{playback.last=performance.now();updateCameraSpeed();if(!playback.videoFinished)playback.video?.play().catch(()=>toast('视频暂不能继续。'));playback.audio?.play().catch(()=>{});playback.fadingAudio?.play().catch(()=>{});}playback.paused=p;$('#pause-play').textContent=p?'▶':'Ⅱ';$('#pause-play').setAttribute('aria-label',p?'继续':'暂停');}
