function endPlayback(){stopMusicMix();playback.running=false;sceneToken++;cancelAnimationFrame(playback.raf);filmMap?.stop();restoreVisuals();playback.audio?.pause();playback.audio=null;playback.audioTrip=null;$('#playback').hidden=true;$('#film-stage').classList.remove('cinema-running');}
