async function runAIDesign(t,pending){const endpoint=$('#design-endpoint').value.trim();let url;try{url=new URL(endpoint);if(url.protocol!=='https:'&&url.hostname!=='localhost'&&url.hostname!=='127.0.0.1')throw Error();}catch{toast('请先填写有效的 HTTPS 设计服务地址。');return;}const b=$('#run-ai-layout');b.disabled=true;try{await measureMedia(t);const response=await fetch(url.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:1,task:'layout_only',palette:pending.palette,allowedLayouts:['auto','single','diptych'],stops:t.stops.map(s=>({media:s.media.map(m=>({kind:m.type.startsWith('video')?'video':'image',ratio:m.ratio||null})),textLength:s.note.length}))})});if(!response.ok)throw Error('设计服务返回 '+response.status);const result=await response.json();if(!['auto','single','diptych'].includes(result.layout))throw Error('设计服务未返回支持的版式');t.design={...t.design,palette:pending.palette,layout:result.layout};state.settings.designEndpoint=url.href;save();openSpreadDesign(t.id);toast('AI 版式已应用。');}catch(e){toast('AI 设计未完成：'+e.message);}finally{b.disabled=false;}}
